<?php
 namespace Pterodactyl\Http\Controllers\Auth; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Illuminate\Auth\AuthManager; use Illuminate\Http\JsonResponse; use Illuminate\Auth\Events\Failed; use Illuminate\Container\Container; use Illuminate\Support\Facades\Event; use Pterodactyl\Events\Auth\DirectLogin; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Http\Controllers\Controller; use Illuminate\Contracts\Auth\Authenticatable; use Illuminate\Foundation\Auth\AuthenticatesUsers; abstract class AbstractLoginController extends Controller { use AuthenticatesUsers; protected AuthManager $auth; protected int $lockoutTime; protected int $maxLoginAttempts; protected string $redirectTo = '/'; public function __construct() { $this->lockoutTime = config('auth.lockout.time'); $this->maxLoginAttempts = config('auth.lockout.attempts'); $this->auth = Container::getInstance()->make(AuthManager::class); } protected function sendFailedLoginResponse(Request $request, ?Authenticatable $user = null, ?string $message = null) { $this->incrementLoginAttempts($request); $this->fireFailedLoginEvent($user, [ $this->getField($request->input('user')) => $request->input('user'), ]); if ($request->route()->named('auth.login-checkpoint')) { throw new DisplayException($message ?? trans('auth.two_factor.checkpoint_failed')); } throw new DisplayException(trans('auth.failed')); } protected function sendLoginResponse(User $user, Request $request): JsonResponse { $request->session()->remove('auth_confirmation_token'); $request->session()->regenerate(); $this->clearLoginAttempts($request); $this->auth->guard()->login($user, true); \Pterodactyl\Services\Dezerx\Security\Security::remember($user, $request->ip()); Event::dispatch(new DirectLogin($user, true)); return new JsonResponse([ 'data' => [ 'complete' => true, 'intended' => $this->redirectPath(), 'user' => $user->toVueObject(), ], ]); } protected function getField(?string $input = null): string { return ($input && str_contains($input, '@')) ? 'email' : 'username'; } protected function fireFailedLoginEvent(?Authenticatable $user = null, array $credentials = []) { Event::dispatch(new Failed('auth', $user, $credentials)); } } 